let pendingUpload = null;
function read(k, fallback) { try { const v = localStorage.getItem(k); return v ? JSON.parse(v) : fallback; } catch { return fallback; } }
function save(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch {} }
async function loadExchangeRates(){const cache=read('ch-fx-cache',null);if(cache?.rates&&cache.nextUpdate>Date.now())rates=cache.rates;else{try{const response=await fetch('https://open.er-api.com/v6/latest/USD');if(!response.ok)throw new Error('Rate service unavailable');const data=await response.json();if(data.result!=='success'||!data.rates)throw new Error('Rate service returned invalid data');rates=data.rates;save('ch-fx-cache',{rates,nextUpdate:(data.time_next_update_unix||Date.now()/1000+86400)*1000,lastUpdate:data.time_last_update_utc});}catch{if(cache?.rates)rates=cache.rates;}}const cacheNow=read('ch-fx-cache',null);const el=document.getElementById('fx-update');if(el)el.textContent=cacheNow?.lastUpdate?new Date(cacheNow.lastUpdate).toLocaleDateString(locales[state.language]):'reference rates unavailable';renderProducts();if(state.view==='saved')renderSaved();}
function requireBackend() { if (!supabase) { toast(translations[state.language]?.setupRequired || 'Connect Supabase in supabase-config.js to use accounts, listings, uploads, and checkout.'); return false; } return true; }
async function handlePaymentReturn(){const url=new URL(window.location.href);if(url.searchParams.get('checkout')!=='return')return;const txRef=url.searchParams.get('tx_ref')||'';const orderId=txRef.startsWith('CH-')?txRef.slice(3):'';if(orderId&&state.user){const {data,error}=await supabase.from('orders').select('status').eq('id',orderId).eq('buyer_id',state.user.id).maybeSingle();if(error)toast(error.message);else if(data?.status==='paid')toast('Payment confirmed. Your order is in your account.');else if(data)toast('Payment received by the provider; final confirmation is processing.');else toast('We could not find that order in your account.');}else toast('Payment return received. Log in to check your order status.');window.history.replaceState({},document.title,window.location.pathname);}
async function initializeBackend() {
  const banner=document.getElementById('backend-status');
  if(!SUPABASE_URL||!SUPABASE_PUBLISHABLE_KEY){banner.textContent='Setup required: add your Supabase project URL and publishable key to supabase-config.js to activate accounts, products, uploads, and checkout.';banner.classList.add('needs-setup');return;}
  try {
    const { createClient } = await import('https://esm.sh/@supabase/supabase-js@2');
    supabase=createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
    const {data:{session},error}=await supabase.auth.getSession();if(error)throw error;
    state.user=session?.user?{id:session.user.id,name:session.user.user_metadata?.display_name||session.user.email?.split('@')[0]||'Maker',email:session.user.email}:null;
    await refreshBackendData();banner.textContent='Connected to Crochet Haven services.';banner.classList.add('connected');await handlePaymentReturn();
    supabase.auth.onAuthStateChange(async(_event,next)=>{state.user=next?.user?{id:next.user.id,name:next.user.user_metadata?.display_name||next.user.email?.split('@')[0]||'Maker',email:next.user.email}:null;try{await refreshBackendData();renderProducts();renderLessons();renderFeed();renderAccount();}catch(err){toast(err.message||'Could not load your account data.');}});
    renderProducts();renderLessons();renderFeed();renderAccount();if(state.view==='seller')renderSeller();
  } catch(error){banner.textContent=`Could not connect to Supabase: ${error.message}`;banner.classList.add('needs-setup');}
}
async function refreshBackendData() {
  if (!supabase) return;
  const [productResult, lessonResult, postResult] = await Promise.all([
    supabase.from('products').select('id,title,description,category,image_urls,price_minor,currency,stock,shipping_mode,shops!inner(id,name,country_code,status)').eq('is_active',true).eq('shops.status','approved').order('created_at',{ascending:false}),
    supabase.from('tutorials').select('id,title,description,level,video_url,duration_seconds,thumbnail_url').eq('is_published',true).order('created_at',{ascending:false}),
    supabase.from('community_posts').select('id,body,image_url,likes_count,created_at,profiles!inner(display_name,country_code)').eq('is_published',true).order('created_at',{ascending:false}).limit(30)
  ]);
  if(productResult.error) throw productResult.error;
  if(lessonResult.error) throw lessonResult.error;
  if(postResult.error) throw postResult.error;
  products = (productResult.data||[]).map(p=>({id:p.id,name:p.title,description:p.description,maker:p.shops.name,country:p.shops.country_code,category:p.category,price:Number(p.price_minor)/(['JPY'].includes(p.currency)?1:100),currency:p.currency,emoji:'🧶',color:'rose',badge:'',shipping:p.shipping_mode==='platform'?'platform':'seller',image:p.image_urls?.[0]}));
  lessons = (lessonResult.data||[]).map(l=>({id:l.id,title:l.title,teacher:'Crochet Haven teacher',level:l.level[0].toUpperCase()+l.level.slice(1),length:`${Math.max(1,Math.round((l.duration_seconds||600)/60))} min`,icon:'🧶',color:'lavender',desc:l.description,videoUrl:l.video_url}));
  state.posts = (postResult.data||[]).map(p=>({id:p.id,name:p.profiles.display_name||'Maker',location:p.profiles.country_code||'Crochet Haven',time:new Date(p.created_at).toLocaleDateString(locales[state.language]),text:p.body,icon:'🧶',color:'rose',likes:p.likes_count||0,image:p.image_url}));
  state.saved=state.user?((await supabase.from('favorites').select('product_id').eq('user_id',state.user.id)).data||[]).map(x=>x.product_id):[];
  if(state.user){const {data:shopData,error:shopError}=await supabase.from('shops').select('*').eq('owner_id',state.user.id).maybeSingle();if(shopError)throw shopError;if(shopData){const {data:shopProducts,error:shopProductsError}=await supabase.from('products').select('id').eq('shop_id',shopData.id);if(shopProductsError)throw shopProductsError;state.shop={...shopData,country:shopData.country_code,products:shopProducts||[]};}else state.shop=null;}else state.shop=null;
}
function convertPrice(value,baseCurrency='USD'){return value*(rates[state.currency]||1)/(rates[baseCurrency]||1);}
function money(value,baseCurrency=state.currency) { const amount=convertPrice(value,baseCurrency);try{return new Intl.NumberFormat(locales[state.language]||'en-US',{style:'currency',currency:state.currency,maximumFractionDigits:['JPY','KES','INR'].includes(state.currency)?0:2}).format(amount);}catch{return `${state.currency} ${amount.toFixed(2)}`;} }
