function applyLanguage() {
  const t=translations[state.language]||translations.en;
  document.documentElement.lang=state.language;document.documentElement.dir=state.language==='ar'?'rtl':'ltr';
  document.querySelectorAll('.desktop-nav [data-view]').forEach((el,i)=>el.textContent=[t.shop,t.learn,t.community][i]);
  const mobile=document.querySelectorAll('.mobile-nav button');if(mobile.length){mobile[0].lastChild.textContent=t.home;mobile[1].lastChild.textContent=t.learn;mobile[2].lastChild.textContent=t.community;mobile[3].childNodes[1].textContent=t.bag+' ';mobile[4].lastChild.textContent=t.account;}
  document.querySelector('.announcement').innerHTML='<span>✦</span> '+pageCopy[state.language].announcement;document.querySelector('.hero-copy>p').textContent=pageCopy[state.language].heroDesc;document.querySelector('.trust-line>span:last-child').innerHTML=pageCopy[state.language].trust;document.querySelector('#learn-view .subpage-hero p').textContent=pageCopy[state.language].learnDesc;document.querySelector('.community-hero p').textContent=pageCopy[state.language].communityDesc;document.querySelector('.maker-banner .eyebrow').textContent=pageCopy[state.language].makerEyebrow;document.querySelector('.newsletter .section-kicker').textContent=pageCopy[state.language].newsletterEyebrow;document.querySelector('.hero h1').innerHTML=t.hero;document.querySelector('.hero-actions .button').childNodes[0].textContent=t.browse+' ';document.querySelector('.hero-actions .text-button').childNodes[0].textContent=t.learnCta+' ';document.getElementById('product-search').placeholder=t.search;
  document.querySelector('.category-strip .section-kicker').textContent=t.categoryIntro;
  document.querySelector('.collection .section-heading .section-kicker').textContent=t.productIntro;document.querySelector('.collection .section-heading h2').innerHTML=t.featuredTitle;document.querySelector('#all-products').childNodes[0].textContent=t.shopAll+' ';
  const lessonHeading=document.querySelector('.lesson-section .section-heading');lessonHeading.querySelector('.section-kicker').textContent=t.lessonIntro;lessonHeading.querySelector('h2').innerHTML=t.lessonTitle;const communityHeading=document.querySelector('.community-feed .section-heading');communityHeading.querySelector('.section-kicker').textContent=t.communityIntro;communityHeading.querySelector('h2').innerHTML=t.communityTitle;
  document.querySelector('.community-hero .button').childNodes[0].textContent=t.share+' ';document.querySelector('.newsletter h2').innerHTML=t.newsletterTitle;document.querySelector('.newsletter p').textContent=t.newsletterBody;document.querySelector('#newsletter-form button').childNodes[0].textContent=t.newsletterButton+' ';document.getElementById('patterns-button').textContent=t.learnCta+' →';
  document.querySelector('.maker-banner h2').innerHTML=t.makerTitle;document.querySelector('.maker-banner p').textContent=t.makerBody;document.getElementById('become-seller').childNodes[0].textContent=t.apply+' ';
  const page=pageCopy[state.language]||pageCopy.en;document.querySelector('#account-view h1').innerHTML=page.accountTitle;document.querySelector('#account-view>section>p').textContent=page.accountIntro;document.querySelector('#seller-view h1').innerHTML=page.sellerTitle;document.querySelector('#seller-view>section>p').textContent=page.sellerIntro;document.querySelector('#saved-view h1').innerHTML=page.savedTitle;document.querySelector('#saved-view>section>p').textContent=page.savedIntro;document.querySelector('#orders-card strong').textContent=t.orders;document.querySelector('#orders-card small').textContent=page.ordersCard;document.querySelector('#seller-card strong').textContent=t.sellerShop;document.querySelector('#seller-card small').textContent=page.sellerCard;document.querySelector('#saved-card strong').textContent=t.saved;document.querySelector('#saved-card small').textContent=page.savedCard;
  const levels=document.getElementById('lesson-level');levels.options[0].textContent=t.levels;[...levels.options].slice(1).forEach(o=>o.textContent=localizedLevel(o.value));document.querySelector('.lesson-section .sort-wrap').childNodes[0].textContent='Level ';document.getElementById('sort-select').options[0].textContent=t.featured;document.getElementById('sort-select').options[1].textContent=t.priceLow;document.getElementById('sort-select').options[2].textContent=t.priceHigh;document.querySelector('.sort-wrap').childNodes[0].textContent=t.sort+' ';
  document.getElementById('currency').value=state.currency;document.getElementById('language').value=state.language;
  renderCategories();renderFilters();renderProducts();renderLessons();renderFeed();if(state.view==='saved')renderSaved();if(state.view==='account')renderAccount();if(state.view==='seller')renderSeller();
}
function escapeHTML(s='') { return String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }
function allProducts() { return products; }
function toast(msg) { const el = document.getElementById('toast'); el.textContent = msg; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2800); }
function setView(name) { state.view = name; document.querySelectorAll('.view').forEach(e => e.classList.toggle('hidden', e.id !== `${name}-view`)); document.querySelectorAll('[data-view]').forEach(e => e.classList.toggle('active', e.dataset.view === name)); window.scrollTo({ top: 0, behavior: 'smooth' }); if (name === 'saved') renderSaved(); if (name === 'seller') renderSeller(); if (name === 'account') renderAccount(); }
function renderCategories() { document.getElementById('category-list').innerHTML = categories.map(c => `<button class="category-item ${state.category===c.name?'selected':''}" data-category="${escapeHTML(c.name)}"><span class="category-icon">${c.icon}</span><span>${escapeHTML(categoryLabel(c.name))}</span></button>`).join(''); }
function renderFilters() { document.getElementById('filters').innerHTML = ['All pieces','Bags','Toys','Home','Wearables','Flowers'].map(x => `<button class="filter-chip ${state.category===x?'selected':''}" data-category="${x}">${escapeHTML(categoryLabel(x))}</button>`).join(''); }
function renderProducts() {
  let list = allProducts().filter(p => (state.category==='All pieces'||p.category===state.category) && `${p.name} ${p.maker} ${p.category} ${p.country}`.toLowerCase().includes(state.search.toLowerCase()));
  if (state.sort==='price-low') list.sort((a,b)=>convertPrice(a.price,a.currency)-convertPrice(b.price,b.currency)); if (state.sort==='price-high') list.sort((a,b)=>convertPrice(b.price,b.currency)-convertPrice(a.price,a.currency));
  const grid = document.getElementById('product-grid');
  grid.innerHTML = list.length ? list.map((p,i)=>`<article class="product-card" style="--delay:${i*.05}s"><div class="product-photo ${p.color}"><div class="product-art">${p.emoji}</div>${p.image?`<img class="product-upload" src="${escapeHTML(p.image)}" alt="${escapeHTML(p.name)}">`:''}${p.badge?`<span class="product-badge">${escapeHTML(p.badge)}</span>`:''}<button class="heart-button ${state.saved.includes(p.id)?'saved':''}" data-save="${p.id}" aria-label="Save ${escapeHTML(p.name)}">${state.saved.includes(p.id)?'♥':'♡'}</button><button class="quick-add" data-add="${p.id}">Add to bag <span>＋</span></button></div><div class="product-meta"><div><span class="product-category">${escapeHTML(categoryLabel(p.category))}</span><h3>${escapeHTML(p.name)}</h3><span class="maker-line">by ${escapeHTML(p.maker)} · ${escapeHTML(p.country)}</span></div><strong>${money(p.price,p.currency)}</strong></div><div class="shipping-label"><span>✳</span> ${p.shipping==='platform'?'Crochet Haven shipping':'Maker-arranged shipping'}</div></article>`).join('') : `<div class="empty-state"><span>🧶</span><h3>${tr('searchEmpty')}</h3><p>${supabase?'Be the first maker to publish a piece.':'Connect your Supabase project to load marketplace listings.'}</p></div>`;
  document.getElementById('load-more').classList.toggle('hidden', list.length < 4);
}
function renderLessons() { const level=document.getElementById('lesson-level')?.value||'all';const list=lessons.filter(x=>level==='all'||x.level.toLowerCase()===level.toLowerCase());document.getElementById('lesson-grid').innerHTML=list.length?list.map(l=>`<article class="lesson-card"><button class="lesson-art ${l.color}" data-lesson="${escapeHTML(l.title)}"><span>🧶</span><i>▶</i></button><div class="lesson-meta"><div class="lesson-tags"><span>${escapeHTML(localizedLevel(l.level))}</span><span>${escapeHTML(l.length)}</span></div><h3>${escapeHTML(l.title)}</h3><p>${escapeHTML(l.desc)}</p><div class="lesson-teacher">${escapeHTML(l.teacher)} <button data-lesson="${escapeHTML(l.title)}">Watch lesson →</button></div></div></article>`).join(''):`<div class="empty-state"><span>🪡</span><h3>${tr('lessonEmpty')}</h3><p>Teachers can submit a lesson for approval.</p></div>`; }
async function openComments(index) {
  if(!requireBackend())return;
  if(!state.user){signInModal('login');return;}
  const post=state.posts[index];if(!post?.id)return;
  const {data,error}=await supabase.from('community_comments').select('id,body,created_at,profiles(display_name)').eq('post_id',post.id).order('created_at',{ascending:true}).limit(100);
  if(error)throw error;
  const comments=data||[];
  const list=comments.length?comments.map(c=>'<article class="comment-entry"><strong>'+escapeHTML(c.profiles?.display_name||'Maker')+'</strong><small>'+new Date(c.created_at).toLocaleString(locales[state.language])+'</small><p>'+escapeHTML(c.body)+'</p></article>').join(''):'<p class="form-hint">No comments yet. Start the conversation.</p>';
  openModal('Comments on this project','<div class="comment-list">'+list+'</div><label class="field-label">Add a comment<textarea id="comment-body" maxlength="500" required></textarea></label>','Post comment');
  document.getElementById('modal-root').dataset.commentPostId=post.id;
}
async function shareCommunityPost(index) {
  const post=state.posts[index];if(!post?.id)return;
  const url=new URL(window.location.href);url.hash='community-post-'+post.id;
  if(navigator.share){try{await navigator.share({title:'Crochet Haven community post',text:post.text,url:url.toString()});return;}catch(error){if(error?.name==='AbortError')return;}}
  if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(url.toString());toast('Project link copied.');return;}
  window.prompt('Copy this project link',url.toString());
}
function renderFeed() { document.getElementById('feed-grid').innerHTML=state.posts.length?state.posts.map((p,i)=>`<article class="feed-card" id="community-post-${escapeHTML(p.id)}"><div class="feed-person"><span class="person-avatar avatar-${i%4}">${escapeHTML(p.name[0])}</span><div><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.location)} · ${escapeHTML(p.time)}</small></div><button class="more-button" data-post-share="${i}" aria-label="Share project">↗</button></div><p>${escapeHTML(p.text)}</p><div class="feed-art ${p.color}">${p.image?`<img class="feed-photo" src="${escapeHTML(p.image)}" alt="Crochet project shared by ${escapeHTML(p.name)}">`:p.icon}</div><div class="feed-actions"><button data-like="${i}">♡ ${p.likes} cheers</button><button data-comment="${i}">Comment</button></div></article>`).join(''):`<div class="empty-state"><span>🧶</span><h3>${tr('communityEmpty')}</h3><p>Sign in to share a crochet project with the community.</p></div>`; }
function updateCart() { const n=state.cart.reduce((sum,x)=>sum+x.qty,0); document.getElementById('cart-count').textContent=n; document.getElementById('mobile-count').textContent=n; }
function renderSaved() { const host=document.getElementById('saved-content'); const ids=state.saved; const ps=allProducts().filter(p=>ids.includes(p.id)); host.innerHTML=ps.length?`<div class="product-grid">${ps.map(p=>`<article class="product-card"><div class="product-photo ${p.color}"><div class="product-art">${p.emoji}</div><button class="heart-button saved" data-save="${p.id}">♥</button><button class="quick-add" data-add="${p.id}">Add to bag <span>＋</span></button></div><div class="product-meta"><div><h3>${escapeHTML(p.name)}</h3><span class="maker-line">by ${escapeHTML(p.maker)}</span></div><strong>${money(p.price,p.currency)}</strong></div></article>`).join('')}</div>`:'<div class="empty-state"><span>♡</span><h3>Your saved collection starts here</h3><p>Tap the heart on any piece to keep it close.</p><button class="button button-dark" data-view="shop">Explore the marketplace →</button></div>'; }
async function toggleFavorite(id){if(!requireBackend())return;if(!state.user){signInModal('login');return;}const exists=state.saved.includes(id);const result=exists?await supabase.from('favorites').delete().eq('user_id',state.user.id).eq('product_id',id):await supabase.from('favorites').insert({user_id:state.user.id,product_id:id});if(result.error){toast(result.error.message);return;}state.saved=exists?state.saved.filter(x=>x!==id):[...state.saved,id];renderProducts();if(state.view==='saved')renderSaved();}
async function toggleLike(index){if(!requireBackend())return;if(!state.user){signInModal('login');return;}const post=state.posts[index];const {data,error}=await supabase.rpc('toggle_post_like',{p_post_id:post.id});if(error){toast(error.message);return;}post.likes=data;renderFeed();}
async function showOrders() { if(!requireBackend())return;if(!state.user){signInModal('login');return;}const {data,error}=await supabase.from('orders').select('id,status,created_at,total_minor,currency,order_items(product_title,quantity)').eq('buyer_id',state.user.id).order('created_at',{ascending:false});if(error){toast(error.message);return;}const body=data?.length?`<div class="order-list">${data.map(o=>`<article class="order-row"><strong>${new Date(o.created_at).toLocaleDateString(locales[state.language])} · ${money(Number(o.total_minor)/(o.currency==='JPY'?1:100),o.currency)}</strong><span>${escapeHTML(o.status)}</span><small>${(o.order_items||[]).map(i=>escapeHTML(i.product_title)+' × '+i.quantity).join(', ')}</small></article>`).join('')}</div>`:'<p>You have no orders yet.</p>';openModal('Your orders',body,'Close');}
function renderAccount() { document.getElementById('signin-note').innerHTML=state.user?'<div class="signed-in"><span class="person-avatar">'+escapeHTML((state.user.name||'S')[0].toUpperCase())+'</span><div><strong>'+escapeHTML(state.user.name)+'</strong><small>'+escapeHTML(state.user.email)+'</small></div><button class="text-button" id="signout">Sign out</button></div>':'<div class="signin-panel"><span>✿</span><div><strong>'+tr('accountWelcome')+'</strong><p>'+tr('accountPrompt')+'</p></div><button class="button button-dark" id="signin-button">'+tr('signIn')+'</button></div>'; }
function renderSeller() { const host=document.getElementById('seller-content'); if(!state.user){host.innerHTML='<div class="signin-panel"><span>🪡</span><div><strong>Every shop begins with a maker.</strong><p>Join or sign in to apply for your own Crochet Haven shop.</p></div><button class="button button-dark" id="signin-button">Sign in / Join us</button></div>';return;} if(!state.shop){host.innerHTML='<div class="seller-apply"><div class="seller-apply-art">🧶</div><h2>Your hands make good things.</h2><p>Tell us a little about your work. New shops are reviewed by our team before selling, so makers can build with confidence.</p><button class="button button-dark" id="apply-shop">Apply to open a shop →</button><div class="seller-perks"><span>✳ 10% fee on successful orders</span><span>✳ Choose seller or platform shipping</span><span>✳ Sell to customers around the world</span></div></div>';return;}
  const approved=state.shop.status==='approved', payoutReady=Boolean(state.shop.flutterwave_subaccount_id); host.innerHTML=`<div class="seller-dashboard"><div class="seller-status ${approved?'approved':''}"><span>${approved?'✿':'◷'}</span><div><strong>${approved?'Your shop is open':'Application under review'}</strong><small>${approved?'Your maker shop is approved and ready for listings.':'We’ll review your shop details before you can publish products.'}</small></div></div><div class="seller-dashboard-grid"><div class="seller-panel"><div class="section-kicker">YOUR SHOP</div><h2>${escapeHTML(state.shop.name)}</h2><p>${escapeHTML(state.shop.description)}</p><div class="seller-stat-row"><div><strong>${(state.shop.products||[]).length}</strong><span>listings</span></div><div><strong>10%</strong><span>platform fee</span></div><div><strong>${escapeHTML(state.shop.country)}</strong><span>based in</span></div></div></div><div class="seller-panel seller-add-panel"><div class="section-kicker">SHARE WHAT YOU MAKE</div><h3>New handmade piece</h3><p>Add a sample listing to your shop.</p><button class="button button-dark" id="add-listing" ${approved?'':'disabled'}>＋ Add a product</button>${approved?'':'<small>Your listings unlock after approval.</small>'}</div></div>${approved?'<div class="seller-panel payout-panel"><div class="section-kicker">SELLER PAYOUTS</div><h3>'+(payoutReady?'Payout account connected':'Set up your payouts')+'</h3><p>'+(payoutReady?'Your shop is connected to Flutterwave for split settlements. Your bank details are not displayed here.':'Connect a bank account to receive your share of customer payments. You will enter your details securely after approval.')+'</p>'+(payoutReady?'<span class="seller-status approved"><span>✓</span><strong>Ready for checkout</strong></span>':'<button class="button button-dark" id="setup-payout">Set up payout account →</button>')+'</div>':''}</div>`;
}
function openModal(title, body, submitText='Continue') { const root=document.getElementById('modal-root'); root.innerHTML=`<div class="modal-backdrop" data-dismiss="true"><section class="modal" role="dialog" aria-modal="true" aria-label="${escapeHTML(title)}"><button class="modal-close" data-close aria-label="Close">×</button><div class="eyebrow">CROCHET HAVEN</div><h2>${title}</h2>${body}<div class="modal-error" id="modal-error"></div><div class="modal-actions"><button class="button button-outline" data-close>Cancel</button><button class="button button-dark" id="modal-submit">${submitText}</button></div></section></div>`; document.body.classList.add('modal-open'); }
function closeModal() { document.getElementById('modal-root').innerHTML=''; document.body.classList.remove('modal-open'); }
function signInModal(mode='register') { openModal('Welcome, <em>maker.</em>', `<div class="auth-switch"><button type="button" data-auth-mode="login" class="${mode==='login'?'active':''}">Log in</button><button type="button" data-auth-mode="register" class="${mode==='register'?'active':''}">Create account</button></div><label class="field-label auth-name" ${mode==='login'?'hidden':''}>Your name<input id="form-name" ${mode==='login'?'':'required'} placeholder="e.g. Shirleen"></label><label class="field-label">Email address<input id="form-email" type="email" required autocomplete="email" placeholder="you@example.com"></label><label class="field-label">Password<input id="form-password" type="password" required minlength="8" autocomplete="${mode==='login'?'current-password':'new-password'}" placeholder="At least 8 characters"></label><div class="oauth-row"><button type="button" data-oauth="Google">Continue with Google</button><button type="button" data-oauth="Apple">Continue with Apple</button></div><p class="form-hint">Your password is managed by Supabase Auth. Enable Google or Apple OAuth in your Supabase dashboard to use those sign-in options.</p>`, mode==='login'?'Log in':'Create my account'); document.getElementById('modal-root').dataset.authMode=mode; }
function sellerModal() { openModal('Tell us what you <em>make.</em>', '<label class="field-label">Shop name<input id="shop-name" required maxlength="48" placeholder="e.g. Little Loop Studio"></label><label class="field-label">Where are you based?<select id="shop-country"><option value="KE">Kenya</option><option value="US">United States</option><option value="GB">United Kingdom</option><option value="GH">Ghana</option><option value="PT">Portugal</option><option value="CA">Canada</option><option value="AU">Australia</option><option value="FR">France</option><option value="IN">India</option><option value="JP">Japan</option><option value="CH">Switzerland</option><option value="ZA">South Africa</option></select></label><label class="field-label">A little about your work<textarea id="shop-description" required maxlength="240" placeholder="What do you love making?"></textarea></label><div class="form-hint">Seller approval is required. Shipping can be arranged by you or by Crochet Haven. A 10% commission applies to completed sales.</div>', 'Send application'); }
async function payoutModal() {
  if(!requireBackend()||!state.user||!state.shop||state.shop.status!=='approved')throw new Error('Only an approved shop owner can set up payouts.');
  if(state.shop.flutterwave_subaccount_id){toast('Your payout account is already connected.');return;}
  const {data,error}=await supabase.functions.invoke('seller-payout-onboarding',{body:{action:'banks'}});
  if(error)throw error;
  const banks=data?.banks||[];
  if(!banks.length)throw new Error(data?.error||'No payout banks are currently available for your shop country.');
  const options=banks.map(b=>'<option value="'+escapeHTML(b.code)+'">'+escapeHTML(b.name)+'</option>').join('');
  openModal('Set up your <em>payouts.</em>','<p class="form-hint">Your shop is approved. Enter the bank account where you want to receive your sales proceeds.</p><label class="field-label">Bank<select id="payout-bank" required><option value="">Choose your bank</option>'+options+'</select></label><label class="field-label">Account number<input id="payout-account-number" inputmode="numeric" autocomplete="off" required maxlength="34" placeholder="Your bank account number"></label><label class="field-label">Mobile number<input id="payout-phone" type="tel" autocomplete="tel" required placeholder="+254 7xx xxx xxx"></label><label class="field-label payout-consent"><input id="payout-consent" type="checkbox"> I confirm that this is my bank account and consent to Crochet Haven sending these details to Flutterwave to create my seller settlement account.</label><p class="form-hint">Your bank account number is sent securely to Flutterwave and is not saved in Crochet Haven’s public database. Only the Flutterwave subaccount reference is stored.</p>','Connect payout account');
}

function tutorialModal(){if(!state.user){signInModal('login');return;}openModal('Submit a crochet lesson','<label class="field-label">Lesson title<input id="tutorial-title" required maxlength="160"></label><label class="field-label">Description<textarea id="tutorial-description" required maxlength="2000"></textarea></label><label class="field-label">Skill level<select id="tutorial-level"><option value="beginner">Beginner</option><option value="intermediate">Intermediate</option><option value="advanced">Advanced</option><option value="pro">Pro</option></select></label><label class="field-label">HTTPS video link<input id="tutorial-url" type="url" required placeholder="https://..."></label><label class="field-label">Lesson length (minutes)<input id="tutorial-duration" type="number" min="1" max="360" value="10" required></label><p class="form-hint">New lessons are saved as drafts and require administrator review before appearing publicly.</p>','Submit for review');}
function addProductModal() { pendingUpload=null;openModal('Publish a handmade piece','<label class="field-label">Piece name<input id="new-title" required maxlength="120"></label><label class="field-label">Description<textarea id="new-description" required maxlength="2000"></textarea></label><label class="upload-label">Product photo (JPEG, PNG, WebP; up to 5 MB)<input id="product-image" type="file" accept="image/jpeg,image/png,image/webp"><img class="upload-preview hidden" alt="Product image preview"></label><div class="form-row"><label class="field-label">Category<select id="new-category"><option>Bags</option><option>Toys</option><option>Home</option><option>Wearables</option><option>Flowers</option></select></label><label class="field-label">Price<input id="new-price" type="number" min="1" step="0.01" required></label></div><label class="field-label">Shipping fee in listing currency<input id="shipping-fee" type="number" min="0" step="0.01" value="0"></label><label class="field-label">Fulfillment<select id="new-shipping"><option value="seller">Maker arranges delivery</option><option value="platform">Crochet Haven coordinates delivery</option></select></label><label class="field-label">Listing currency<select id="new-currency"><option>USD</option><option>EUR</option><option>GBP</option><option>KES</option><option>CAD</option><option>AUD</option><option>JPY</option><option>INR</option><option>CHF</option><option>ZAR</option></select></label><p class="form-hint">Enter the delivery charge above. Crochet Haven-coordinated orders require manual fulfillment until carrier integrations are added.</p>','Publish listing'); }
function addToCart(id) { const p=allProducts().find(x=>x.id===id); if(!p)return; const item=state.cart.find(x=>x.id===id); if(item)item.qty++;else state.cart.push({id,qty:1}); updateCart(); toast(`${p.name} added to your bag`); }
async function uploadPendingImage(folder) { if(!pendingUpload)return null;if(!requireBackend())throw new Error('Backend is not connected.');const blob=await (await fetch(pendingUpload)).blob();const path=`${state.user.id}/${folder}/${crypto.randomUUID()}.jpg`;const {error}=await supabase.storage.from('marketplace-media').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw error;return supabase.storage.from('marketplace-media').getPublicUrl(path).data.publicUrl; }
async function imageData(file) { if(!file||!file.type.startsWith('image/'))throw new Error('Choose an image file.');if(file.size>10*1024*1024)throw new Error('Choose an image smaller than 10 MB.');const bitmap=await createImageBitmap(file);const scale=Math.min(1,1200/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.78); }
function cartModal() { const items=state.cart.map(item=>({...item,product:allProducts().find(p=>p.id===item.id)})).filter(x=>x.product); const total=items.reduce((sum,x)=>sum+convertPrice(x.product.price*x.qty,x.product.currency),0); openModal('Your <em>little bag.</em>', items.length?`<div class="cart-lines">${items.map(x=>`<div class="cart-line"><span class="cart-emoji ${x.product.color}">${x.product.emoji}</span><div class="cart-line-info"><strong>${escapeHTML(x.product.name)}</strong><small>${money(x.product.price,x.product.currency)} each</small><div class="qty-control"><button data-qty="${x.id}" data-delta="-1" aria-label="Remove one">−</button><span>${x.qty}</span><button data-qty="${x.id}" data-delta="1" aria-label="Add one">＋</button><button class="remove-item" data-remove="${x.id}">Remove</button></div></div><strong>${money(x.product.price*x.qty,x.product.currency)}</strong></div>`).join('')}<div class="cart-total"><span>Subtotal</span><strong>${money(total)}</strong></div><p class="form-hint">Shipping and final currency conversion are confirmed at checkout.</p></div>`:'<div class="empty-state"><span>🛍</span><h3>Your bag is waiting for something lovely</h3><p>Find a handmade piece to make it yours.</p></div>', items.length?'Continue to checkout':'Keep exploring'); const submit=document.getElementById('modal-submit'); if(!items.length) submit.textContent='Explore pieces'; }
function checkoutModal() { const items=state.cart.map(x=>({...x,p:allProducts().find(p=>p.id===x.id)})).filter(x=>x.p);const orderCurrency=items[0]?.p.currency||'USD';const total=items.reduce((sum,x)=>sum+x.p.price*x.qty,0);openModal('Secure checkout',`<div class="checkout-summary"><span>Subtotal</span><strong>${money(total,orderCurrency)}</strong></div><p class="form-hint">Charged in the seller’s listing currency (${escapeHTML(orderCurrency)}). Display currency conversions are estimates.</p><label class="field-label">Email<input type="email" id="checkout-email" value="${escapeHTML(state.user?.email||'')}" readonly></label><label class="field-label">Recipient name<input id="shipping-name" required></label><label class="field-label">Street address<input id="shipping-address" required></label><div class="form-row"><label class="field-label">City<input id="shipping-city" required></label><label class="field-label">Postal code<input id="shipping-postal"></label></div><label class="field-label">Country<select id="checkout-country"><option value="KE">Kenya</option><option value="US">United States</option><option value="GB">United Kingdom</option><option value="FR">France</option><option value="GH">Ghana</option><option value="PT">Portugal</option><option value="CA">Canada</option><option value="AU">Australia</option><option value="IN">India</option><option value="ZA">South Africa</option><option value="JP">Japan</option><option value="CH">Switzerland</option></select></label><div class="field-label">Payment method<div class="payment-options"><label class="payment-option"><input type="radio" name="payment-method" value="card" checked> Card (Visa / Mastercard)</label><label class="payment-option"><input type="radio" name="payment-method" value="mpesa" ${orderCurrency==='KES'?'':'disabled'}> M-Pesa (KES only)</label></div></div><div class="payment-note"><span>🔒</span><div><strong>Secure payment through Flutterwave</strong><small>You’ll continue to the provider’s checkout. Payments activate after the merchant account and server secrets are configured.</small></div></div>`, 'Continue to payment'); }
function lessonModal(title) { const lesson=lessons.find(x=>x.title===title);const safeVideo=lesson?.videoUrl&&/^https:\/\//i.test(lesson.videoUrl)?lesson.videoUrl:null;const video=safeVideo?`<a class="button button-dark" href="${escapeHTML(safeVideo)}" target="_blank" rel="noopener noreferrer">Open lesson video ↗</a>`:'<p class="form-hint">This tutorial does not have a video URL yet.</p>';openModal(escapeHTML(title),`<div class="video-placeholder ${lesson?.color||'rose'}"><span>▶</span><small>${escapeHTML(lesson?.level||'Lesson')}</small></div><div class="lesson-modal-info"><strong>${lesson?.level||'Lesson'} · ${lesson?.length||''} · ${escapeHTML(lesson?.teacher||'')}</strong><p>${escapeHTML(lesson?.desc||'')}</p>${video}</div>`,'Close'); }
function bindEvents() {
  document.addEventListener('click', e=>{
    const view=e.target.closest('[data-view]'); if(view){e.preventDefault();setView(view.dataset.view);return;}
    const searchToggle=e.target.closest('.search-toggle');if(searchToggle){setView('shop');const field=document.getElementById('product-search');field.scrollIntoView({behavior:'smooth',block:'center'});field.focus({preventScroll:true});return;}
    const cat=e.target.closest('[data-category]'); if(cat){state.category=cat.dataset.category;renderCategories();renderFilters();renderProducts();return;}
    const add=e.target.closest('[data-add]'); if(add){addToCart(add.dataset.add);return;}
    const saveBtn=e.target.closest('[data-save]'); if(saveBtn){toggleFavorite(saveBtn.dataset.save);return;}
    const close=e.target.closest('[data-close]'); if(close || (e.target.matches('[data-dismiss]')&&e.target===e.target.closest('[data-dismiss]'))){closeModal();return;}
    if(e.target.closest('#cart-button')||e.target.closest('#mobile-cart')){cartModal();return;}
    if(e.target.closest('#saved-button')||e.target.closest('#saved-card')){setView('saved');return;}
    if(e.target.closest('#account-button')){setView('account');return;}
    if(e.target.closest('#orders-card')){showOrders();return;}
    if(e.target.closest('#become-seller')||e.target.closest('#footer-seller')||e.target.closest('#seller-card')){setView('seller');return;}
    if(e.target.closest('#teach-lesson')){if(!requireBackend())return;tutorialModal();return;}
    if(e.target.closest('#signin-button')){signInModal();return;}
    const authMode=e.target.closest('[data-auth-mode]');if(authMode){signInModal(authMode.dataset.authMode);return;}
    const oauth=e.target.closest('[data-oauth]');if(oauth){if(!requireBackend())return;supabase.auth.signInWithOAuth({provider:oauth.dataset.oauth.toLowerCase(),options:{redirectTo:window.location.origin}}).then(({error})=>{if(error)toast(error.message);});return;}
    if(e.target.closest('#apply-shop')){sellerModal();return;}
    if(e.target.closest('#setup-payout')){payoutModal().catch(error=>toast(error.message||'Could not load payout setup.'));return;}
    if(e.target.closest('#add-listing')){addProductModal();return;}
    const lesson=e.target.closest('[data-lesson]'); if(lesson){lessonModal(lesson.dataset.lesson);return;}
    if(e.target.closest('#share-project')){pendingUpload=null;openModal('Share a little <em>progress.</em>','<label class="field-label">Your update<textarea id="post-text" required maxlength="280" placeholder="What are you making? What did you learn?"></textarea></label><label class="field-label">Your name<input id="post-name" value="'+escapeHTML(state.user?.name||'Maker')+'" required></label><label class="upload-label">Add a photo of your project<input id="community-image" type="file" accept="image/*"><img class="upload-preview hidden" alt="Project image preview"></label><p class="form-hint">Project photo uploads are stored in your marketplace media bucket.</p>','Share with the community');return;}
    if(e.target.closest('#patterns-button')){setView('learn');document.getElementById('lesson-grid').scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(e.target.closest('#load-more')||e.target.closest('#all-products')){state.category='All pieces';renderCategories();renderFilters();renderProducts();document.getElementById('product-search').focus();return;}
    if(e.target.closest('#signout')){if(!requireBackend())return;supabase.auth.signOut().then(({error})=>{if(error)toast(error.message);});return;}
    const qty=e.target.closest('[data-qty]'); if(qty){const item=state.cart.find(x=>x.id===qty.dataset.qty);if(item){item.qty+=Number(qty.dataset.delta);if(item.qty<1)state.cart=state.cart.filter(x=>x!==item);updateCart();cartModal();}return;}
    const rem=e.target.closest('[data-remove]'); if(rem){state.cart=state.cart.filter(x=>x.id!==rem.dataset.remove);updateCart();cartModal();return;}
    const like=e.target.closest('[data-like]');if(like){toggleLike(like.dataset.like);return;}
    const comment=e.target.closest('[data-comment]');if(comment){openComments(Number(comment.dataset.comment)).catch(error=>toast(error.message||'Could not load comments.'));return;}const postShare=e.target.closest('[data-post-share]');if(postShare){shareCommunityPost(Number(postShare.dataset.postShare)).catch(error=>toast(error.message||'Could not share this project.'));return;}if(e.target.closest('#community-filter')){document.getElementById('feed-grid').scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(e.target.closest('#modal-submit')){handleModalSubmit().catch(error=>{const errorBox=document.getElementById('modal-error');if(errorBox)errorBox.textContent=error.message||'The request could not be completed.';const submit=document.getElementById('modal-submit');if(submit)submit.disabled=false;});return;}
  });
  document.getElementById('product-search').addEventListener('input',e=>{state.search=e.target.value;renderProducts();});
  document.getElementById('sort-select').addEventListener('change',e=>{state.sort=e.target.value;renderProducts();});
  document.getElementById('language').addEventListener('change',e=>{state.language=e.target.value;save('ch-language',state.language);applyLanguage();renderProducts();renderLessons();toast(`Language: ${e.target.options[e.target.selectedIndex].text}`);});
  document.getElementById('currency').addEventListener('change',e=>{state.currency=e.target.value;save('ch-currency',state.currency);renderProducts();if(state.view==='saved')renderSaved();toast(`Showing prices in ${state.currency}`);});
  document.getElementById('lesson-level').addEventListener('change',renderLessons);
  document.addEventListener('change',async e=>{if(!['product-image','community-image'].includes(e.target.id))return;const input=e.target,preview=input.parentElement.querySelector('.upload-preview');try{pendingUpload=await imageData(input.files[0]);preview.src=pendingUpload;preview.classList.remove('hidden');}catch(error){pendingUpload=null;input.value='';toast(error.message||'Could not load that image.');}});
  document.getElementById('newsletter-form').addEventListener('submit',e=>{e.preventDefault();const email=e.currentTarget.querySelector('input[type="email"]').value.trim();signInModal('register');const field=document.getElementById('form-email');if(field){field.value=email;field.focus();}toast('Finish creating your account to join Crochet Haven.');});
}
async function handleModalSubmit() {
  const commentField=document.getElementById('comment-body');
  if(commentField){
    if(!requireBackend()||!state.user)return;
    const body=commentField.value.trim();
    const postId=document.getElementById('modal-root').dataset.commentPostId;
    if(!body)return fail('Write a comment before posting.');
    const {error}=await supabase.from('community_comments').insert({post_id:postId,user_id:state.user.id,body});
    if(error)return fail(error.message);
    const index=state.posts.findIndex(post=>post.id===postId);
    closeModal();await openComments(index);toast('Comment posted.');return;
  }
  const err=document.getElementById('modal-error'); const fail=msg=>{err.textContent=msg;const button=document.getElementById('modal-submit');if(button)button.disabled=false;};
  if(document.getElementById('form-email')){if(!requireBackend())return;const email=document.getElementById('form-email').value.trim(),password=document.getElementById('form-password').value,mode=document.getElementById('modal-root').dataset.authMode;if(!email.includes('@')||password.length<8)return fail('Enter a valid email and a password with at least 8 characters.');if(mode==='login'){const {data,error}=await supabase.auth.signInWithPassword({email,password});if(error)return fail(error.message);state.user={id:data.user.id,name:data.user.user_metadata?.display_name||data.user.email.split('@')[0],email:data.user.email};}else{const name=document.getElementById('form-name').value.trim();if(!name)return fail('Please add your name.');const {data,error}=await supabase.auth.signUp({email,password,options:{data:{display_name:name}}});if(error)return fail(error.message);state.user=data.user?{id:data.user.id,name,email:data.user.email}:null;if(!data.session){closeModal();toast('Check your email to confirm your account, then log in.');return;}}await refreshBackendData();closeModal();renderAccount();toast(`Welcome, ${state.user.name.split(' ')[0]}!`);return;}
  if(document.getElementById('tutorial-title')){if(!requireBackend())return;if(!state.user)return fail('Log in before submitting a lesson.');const title=document.getElementById('tutorial-title').value.trim(),description=document.getElementById('tutorial-description').value.trim(),videoUrl=document.getElementById('tutorial-url').value.trim(),duration=Number(document.getElementById('tutorial-duration').value);if(!/^https:\/\//i.test(videoUrl)||!title||!description||duration<1)return fail('Enter a title, description, secure HTTPS video URL, and lesson length.');const {error}=await supabase.from('tutorials').insert({teacher_id:state.user.id,title,description,level:document.getElementById('tutorial-level').value,video_url:videoUrl,duration_seconds:duration*60,is_published:false});if(error)return fail(error.message);closeModal();toast('Lesson submitted for review.');return;}
  if(document.getElementById('shop-name')){if(!requireBackend())return;if(!state.user)return fail('Create an account and log in first.');const name=document.getElementById('shop-name').value.trim(),desc=document.getElementById('shop-description').value.trim(),country=document.getElementById('shop-country').value;if(name.length<3||!desc)return fail('Add a shop name and a short description to continue.');const slug=name.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')+'-'+state.user.id.slice(0,6);const {data,error}=await supabase.from('shops').insert({owner_id:state.user.id,name,slug,description:desc,country_code:country,status:'pending',shipping_options:['seller','platform']}).select().single();if(error)return fail(error.message);state.shop={...data,country:data.country_code,products:[]};closeModal();renderSeller();toast('Application sent for review.');return;}
  if(document.getElementById('payout-bank')){if(!requireBackend()||!state.user||!state.shop||state.shop.status!=='approved')return fail('An approved shop is required to set up payouts.');const bankCode=document.getElementById('payout-bank').value,accountNumber=document.getElementById('payout-account-number').value.trim(),phone=document.getElementById('payout-phone').value.trim(),consent=document.getElementById('payout-consent').checked;if(!bankCode||accountNumber.length<5||!/^\+?[0-9 ()-]{8,20}$/.test(phone)||!consent)return fail('Choose a bank, enter a valid account number and phone number, and confirm your consent.');const button=document.getElementById('modal-submit');if(button)button.disabled=true;const {data,error}=await supabase.functions.invoke('seller-payout-onboarding',{body:{action:'create',bank_code:bankCode,account_number:accountNumber,phone,consent:true}});if(error)return fail(error.message||'Flutterwave could not connect your payout account.');if(data?.error)return fail(data.error);await refreshBackendData();closeModal();renderSeller();toast('Your payout account is connected.');return;}if(document.getElementById('new-title')){if(!requireBackend())return;if(!state.user||!state.shop||state.shop.status!=='approved')return fail('An approved maker shop is required before publishing products.');const title=document.getElementById('new-title').value.trim(),price=Number(document.getElementById('new-price').value),imageUrl=await uploadPendingImage('products');if(!title||price<=0)return fail('Add a piece name and a price greater than zero.');const currency=document.getElementById('new-currency').value,scale=currency==='JPY'?1:100;const {error}=await supabase.from('products').insert({shop_id:state.shop.id,title,description:document.getElementById('new-description').value.trim(),category:document.getElementById('new-category').value,price_minor:Math.round(price*scale),currency,stock:1,shipping_mode:document.getElementById('new-shipping').value,shipping_minor:Math.round(Number(document.getElementById('shipping-fee').value||0)*scale),image_urls:imageUrl?[imageUrl]:[],is_active:true});if(error)return fail(error.message);await refreshBackendData();closeModal();renderSeller();renderProducts();toast('Your listing is published.');return;}
  if(document.getElementById('post-text')){if(!requireBackend())return;if(!state.user)return fail('Create an account and log in before sharing your work.');const text=document.getElementById('post-text').value.trim();if(!text)return fail('Add a little project update.');const imageUrl=await uploadPendingImage('community');const {error}=await supabase.from('community_posts').insert({user_id:state.user.id,body:text,image_url:imageUrl,is_published:true});if(error)return fail(error.message);await refreshBackendData();closeModal();renderFeed();setView('community');toast('Your project is shared.');return;}
  if(document.getElementById('checkout-email')){if(!requireBackend())return;if(!state.user)return fail('Log in before checkout.');const address={full_name:document.getElementById('shipping-name').value.trim(),address_line_1:document.getElementById('shipping-address').value.trim(),city:document.getElementById('shipping-city').value.trim(),postal_code:document.getElementById('shipping-postal').value.trim(),country_code:document.getElementById('checkout-country').value},payment=document.querySelector('input[name="payment-method"]:checked')?.value||'card';if(!address.full_name||!address.address_line_1||!address.city)return fail('Complete your shipping name, street address, and city.');if(!state.cart.length)return fail('Your bag is empty.');if(state.cart.some(x=>!allProducts().some(p=>p.id===x.id)))return fail('One or more products are no longer available.');if(state.cart.length>1&&new Set(state.cart.map(x=>allProducts().find(p=>p.id===x.id)?.currency)).size>1)return fail('Please check out products with different currencies separately.');if(state.cart.length>1&&new Set(state.cart.map(x=>allProducts().find(p=>p.id===x.id)?.shop_id)).size>1)return fail('Check out one maker’s shop at a time.');document.getElementById('modal-submit').disabled=true;const {data,error}=await supabase.functions.invoke('create-checkout',{body:{items:state.cart.map(x=>({product_id:x.id,quantity:x.qty})),shipping_address:address,payment_method:payment}});if(error)return fail(error.message);if(!data?.checkout_url)return fail(data?.error||'Payment provider did not return a checkout link.');window.location.assign(data.checkout_url);return;}
  if(document.querySelector('.cart-lines')){checkoutModal();return;} closeModal();
}
function init() { document.getElementById('year').textContent=new Date().getFullYear();document.getElementById('currency').value=state.currency;document.getElementById('language').value=state.language;applyLanguage();renderCategories();renderFilters();renderProducts();renderLessons();renderFeed();updateCart();bindEvents();renderAccount();initializeBackend();loadExchangeRates();}
init();
